/**
 * This app's one way to a language model. The page asks through `lib/ai.ts`, which posts here;
 * this route forwards the question to the model service with the app's own token and hands back
 * the answer. There is no provider key in this app or its repository: the token works only for
 * this app, and the service holds the key and the spending limits.
 *
 * Do not edit this file, and do not call a model any other way. What it does for you:
 *
 * 1. Answers only this app's own pages. A request must be JSON (`content-type: application/json`,
 *    else HTTP 415), which a page on another site cannot send without the browser asking first,
 *    and this route never says yes to that; and a browser that names the request's origin
 *    (`Sec-Fetch-Site`) must call it `same-origin` (else HTTP 403). So another site cannot spend
 *    this app's allowance through its visitors' browsers. `askModel` already sends what passes.
 * 2. Slows down one visitor asking too fast: 20 requests a minute per address, kept in memory.
 *    A speed bump, not a guarantee — the service's own limits are the real ones.
 * 3. Checks the request: at least one user message, and at most 8,000 characters in all,
 *    counting the JSON `example`.
 * 4. Answers HTTP 200 for every other outcome it handles. A failure is `{ ok: false, reason, message }`
 *    with `message` written for the screen, so the page always has something to show.
 * 5. Never logs or keeps what was asked or answered.
 *
 * Configuration comes from the deployment: `APP_AI_TOKEN` and `AI_PROXY_URL`. Without them every
 * request answers `not-configured`. `AI_STUB=1` (ignored on Vercel) answers with a sample
 * instead of calling a model, so the page can be built without spending anything.
 */

export const runtime = "nodejs";
export const maxDuration = 30;

type Role = "system" | "user" | "assistant";
type Message = { role: Role; content: string };

type Reason =
  | "not-configured" | "rate-limited" | "too-long" | "bad-request"
  | "unauthorized" | "not-live" | "paused" | "limit-app-day" | "limit-owner-month" | "upstream";

const MESSAGES: Record<Reason, string> = {
  "not-configured": "The assistant isn't set up for this app.",
  unauthorized: "The assistant isn't set up for this app.",
  "not-live": "The assistant isn't set up for this app.",
  paused: "The assistant isn't available right now.",
  upstream: "The assistant isn't available right now.",
  "rate-limited": "That's a lot of questions at once. Wait a moment and try again.",
  "limit-app-day": "The assistant has reached today's limit for this app.",
  "limit-owner-month": "The assistant has reached this month's limit.",
  "too-long": "That's too much text for the assistant; shorten it.",
  "bad-request": "The assistant couldn't read that request.",
};

/** Reasons the model service may answer with. Anything else from it reads as `upstream`. */
const SERVICE_REASONS: readonly Reason[] = ["unauthorized", "not-live", "paused", "limit-app-day", "limit-owner-month", "too-long", "upstream"];

const MAX_PROMPT_CHARS = 8_000;
const MAX_MESSAGES = 40;
const MAX_TOKENS = 1_000;
const MAX_EXAMPLE_CHARS = 2_000;
const PER_MINUTE = 20;
const MAX_VISITORS = 5_000;
const TIMEOUT_MS = 28_000;

const buckets = new Map<string, { tokens: number; at: number }>();

function reply(body: Record<string, unknown>, status = 200): Response {
  return Response.json(body, { status, headers: { "cache-control": "no-store" } });
}

function failure(reason: Reason, retryAfterSeconds?: number): Response {
  return reply({ ok: false, reason, message: MESSAGES[reason], ...(retryAfterSeconds ? { retryAfterSeconds } : {}) });
}

/**
 * Refuses a request that did not come from this app's own pages: HTTP 415 when it is not JSON, 403
 * when the browser says another site sent it. undefined when it may go ahead.
 *
 * A `text/plain` or form POST needs no permission from this route, so any site could make its
 * visitors' browsers send one; JSON makes the browser ask first, and the route never answers that
 * question. `Sec-Fetch-Site` is absent from older browsers and from servers; when present, only
 * `same-origin` (and `none`, the visitor's own action) are let through. Checked before the speed
 * bump, so a refused request costs the visitor nothing.
 */
function refuseForeign(request: Request): Response | undefined {
  const type = request.headers.get("content-type")?.split(";")[0]?.trim().toLowerCase();
  if (type !== "application/json") {
    return reply({ ok: false, reason: "bad-request", message: MESSAGES["bad-request"] }, 415);
  }
  const site = request.headers.get("sec-fetch-site")?.trim().toLowerCase();
  if (site && site !== "same-origin" && site !== "none") {
    return reply({ ok: false, reason: "bad-request", message: MESSAGES["bad-request"] }, 403);
  }
  return undefined;
}

function visitor(request: Request): string {
  const forwarded = request.headers.get("x-forwarded-for")?.split(",")[0]?.trim();
  return forwarded || request.headers.get("x-real-ip")?.trim() || "unknown";
}

/** Takes one request from the visitor's bucket: 0 when it may go ahead, else seconds to wait. */
function take(key: string, now: number): number {
  const refill = (bucket: { tokens: number; at: number }) => Math.min(PER_MINUTE, bucket.tokens + ((now - bucket.at) / 60_000) * PER_MINUTE);
  if (buckets.size >= MAX_VISITORS) {
    for (const [name, bucket] of buckets) if (refill(bucket) >= PER_MINUTE) buckets.delete(name);
    if (buckets.size >= MAX_VISITORS) buckets.clear();
  }
  const previous = buckets.get(key);
  const tokens = previous ? refill(previous) : PER_MINUTE;
  if (tokens < 1) {
    buckets.set(key, { tokens, at: now });
    return Math.max(1, Math.ceil(((1 - tokens) * 60) / PER_MINUTE));
  }
  buckets.set(key, { tokens: tokens - 1, at: now });
  return 0;
}

function asRecord(value: unknown): Record<string, unknown> | undefined {
  return value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : undefined;
}

type Question = { messages: Message[]; lastUser: string; json: boolean; example?: string; maxTokens?: number; temperature?: number };

function readQuestion(body: unknown): Question | Reason {
  const record = asRecord(body);
  const list = record?.messages;
  if (!record || !Array.isArray(list) || list.length === 0 || list.length > MAX_MESSAGES) return "bad-request";
  const messages: Message[] = [];
  for (const entry of list) {
    const message = asRecord(entry);
    const role = message?.role;
    if (role !== "system" && role !== "user" && role !== "assistant") return "bad-request";
    if (typeof message?.content !== "string") return "bad-request";
    messages.push({ role, content: message.content });
  }
  const lastUser = messages.findLast((message) => message.role === "user" && message.content.trim() !== "")?.content;
  if (lastUser === undefined) return "bad-request";

  const json = record.json === true;
  let example: string | undefined;
  if (json && record.example !== undefined) {
    try {
      example = JSON.stringify(record.example);
    } catch {
      return "bad-request";
    }
    if (example === undefined) return "bad-request";
    if (example.length > MAX_EXAMPLE_CHARS) return "too-long";
  }
  // The example travels as JSON text; the model service turns it into the shape to answer in.
  if (messages.reduce((total, message) => total + message.content.length, 0) + (example?.length ?? 0) > MAX_PROMPT_CHARS) return "too-long";

  const maxTokens = typeof record.maxTokens === "number" && Number.isFinite(record.maxTokens)
    ? Math.min(MAX_TOKENS, Math.max(1, Math.round(record.maxTokens)))
    : undefined;
  const temperature = typeof record.temperature === "number" && Number.isFinite(record.temperature)
    ? Math.min(1, Math.max(0, record.temperature))
    : undefined;
  return { messages, lastUser, json, example, maxTokens, temperature };
}

/** The sample answer: the same question always gets the same one. */
function sampleAnswer(question: Question): string {
  if (question.json) return question.example ?? "{}";
  const topic = question.lastUser.replace(/\s+/g, " ").trim().slice(0, 60);
  return `Sample answer about "${topic}". The live app shows the AI model's reply here.`;
}

export async function POST(request: Request): Promise<Response> {
  const refused = refuseForeign(request);
  if (refused) return refused;

  const wait = take(visitor(request), Date.now());
  if (wait > 0) return failure("rate-limited", wait);

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return failure("bad-request");
  }
  const question = readQuestion(body);
  if (typeof question === "string") return failure(question);

  const stub = process.env.AI_STUB;
  if ((stub === "1" || stub === "true") && !process.env.VERCEL) {
    return reply({ ok: true, text: sampleAnswer(question), stub: true });
  }

  const token = process.env.APP_AI_TOKEN;
  const url = process.env.AI_PROXY_URL;
  if (!token || !url || !URL.canParse(url)) return failure("not-configured");

  let answer: Record<string, unknown> | undefined;
  let status: number;
  try {
    const upstream = await fetch(url, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        token,
        messages: question.messages,
        json: question.json,
        ...(question.example !== undefined ? { example: question.example } : {}),
        ...(question.maxTokens !== undefined ? { maxTokens: question.maxTokens } : {}),
        ...(question.temperature !== undefined ? { temperature: question.temperature } : {}),
      }),
      signal: AbortSignal.timeout(TIMEOUT_MS),
      cache: "no-store",
    });
    status = upstream.status;
    answer = asRecord(await upstream.json());
  } catch {
    return failure("upstream");
  }

  if (status >= 200 && status < 300 && answer?.ok === true && typeof answer.text === "string" && answer.text.trim()) {
    return reply({ ok: true, text: answer.text });
  }
  const reason = SERVICE_REASONS.find((known) => known === answer?.reason) ?? (answer?.reason === "schema" ? "paused" : "upstream");
  const retry = answer?.retryAfterSeconds;
  return failure(reason, typeof retry === "number" && Number.isFinite(retry) && retry > 0 ? Math.ceil(retry) : undefined);
}
